let botoesDetalhes=document.querySelectorAll(".product-button"),anoAtual=(botoesDetalhes.forEach(function(t){t.addEventListener("click",function(e){e.preventDefault();e=t.closest(".product-item").querySelector("h4").textContent;alert("Você selecionou: "+e)})}),(new Date).getFullYear()),rodape=document.querySelector("footer p");rodape&&(rodape.textContent+=" - "+anoAtual);